1	/* ============================ Lái xe máy: điều phối chế độ (lái một mình, máy tính) ============================
2	   Spec D-040. Cấu trúc theo explore/drive/index.ts; dùng lại các phần thuần của chế độ ô tô (mạng đường, va chạm, camera sau xe, HUD),
3	   drive/* không bao giờ import ngược từ bike/*.
4	   - Mạng đường DÙNG CHUNG với ô tô: drEnsureNet() của drive/index.ts (dựng một lần cho cả trang; drCollectRuntime chỉ push, dựng net thứ hai sẽ nhân đôi vật cản).
5	   - Thân va chạm: start() đặt drUseBody(BK_BODY), stop() trả DR_CAR_BODY (drive.start() cũng tự đặt lại thân ô tô).
6	   - Mỗi khung: phím → BkInput (keys.ts), grip + gió giật (fx.ts), bkStep với hộp xe tự động gần xe (trNearby), hình xe (model.ts),
7	     camera (camera.ts): mặc định góc thứ nhất trên yên, V trộn sang góc thứ ba (drCamPlace với CONFIG.bike.cam3) trong cam1.mixS; fov / near đổi thì onResize();
8	     mặt đồng hồ (dash.ts) vẽ lại ≤ dash.hz; controls.target theo xe (tâm vùng bóng đổ), HUD (đồng hồ + bản đồ nhỏ của ô tô), exNightStep(dt, false).
9	   - Mắt góc thứ nhất: đo MỘT lần khi người lái thật gắn vào mô hình thật (riderEye: giữa hai xương mắt ở tư thế ngồi nền, hệ thân xe), không theo xương mỗi khung;
10	     chưa có thì cam1.eye. Camera còn sát mắt (smoothstep(mix) < cam1.headMix, bkCamHideHead) thì ẩn đầu + mũ (rider.setFirstPerson). prefers-reduced-motion ⇒ cam1.motionReduced.
11	   - Phím (theo e.code, chỉ khi đang lái, bỏ ô nhập và tổ hợp Ctrl / Meta / Alt; blur / ẩn tab nhả hết): R về làn (bkRecover), Q / E xi nhan trái / phải (bkSignal),
12	     V đổi góc nhìn thứ nhất ↔ thứ ba, H còi (giữ; nhả khi blur / ẩn tab / focus vào ô nhập). Kéo chuột trái / vuốt trên canvas: nhìn quanh (thứ nhất) hoặc quay quanh xe (thứ ba).
13	   - Lớp body 'explore drive bike': khung HUD #drHud và các quy tắc CSS của body.drive áp nguyên; 'bike' cho phần riêng về sau.
14	   - Thoát: explore.exit() gọi bike.stop() rồi tải lại trang. Chưa có: nhiều người (Task 10), cảm ứng (Task 9). Mô hình thật: model.ts (làm nóng qua bkModelSetWarm bên dưới).
15	   - Người lái: rider.ts, nhân vật theo stChar (chung Đi dạo), nạp ở preload() / start() (làm nóng qua stRigSetWarm của stroll/index.ts); chưa về thì xe không người,
16	     về sau stop() thì bỏ. Người gắn vào neo yên của xe nên rời cảnh cùng model.group.
17	   - Âm thanh (sound.ts bkSound): đề máy ở start(), tắt máy ở stop(); mỗi khung một BkSoundIn tái dùng (hộp xe gần dùng lại mảng trNearby của bkStep,
18	     river từ |x| so với mép kè, tunnel từ ô mặt đường dưới xe, mưa = 0 trong đoạn hầm kín); nút 🔊 #drSoundBtn chung với ô tô, bkSound.bind chỉ toggle khi đang lái xe máy.
19	   - Đêm + mưa (fx.ts, Task 7): grip = bkGrip(weatherU.uWet, xe trong đoạn hầm kín) mỗi khung; gió giật cộng bkGustSteer vào steer (BkInput giữ nguyên, chỉ khi v > vBlend);
20	     bkFx (vệt pha ban đêm, bụi nước khi mưa) vào cảnh ở start(), ra ở stop(), cập nhật sau model.place. "Hầm kín" = ô kiểu 'tunnel' và |x| ≤ HR.coverHalf:
21	     ô 'tunnel.tube' gồm cả hai dốc hở (|x| ≤ rampHalf), nơi mặt đường roadOut ướt khi mưa (han-tunnel/materials.ts registerWet).
22	   - Mặt đường nhìn gần (roadFx.ts, Task 8, mốc bỏ được): start() bkRoadSet(true) ⇒ shared.uRoadNear = 1 (nếu CONFIG.bike.road.detail), stop() về 0.
23	   Mỗi khung không cấp phát (D-018). */
24	import * as THREE from 'three';
25	import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
26	import { composer, onResize } from '../../core/postprocessing';
27	import { cam } from '../../views/state';
28	import { CONFIG } from '../../config';
29	import { driveView } from '../../environment/driveRoads';
30	import { drSetGate, type DrNet } from '../drive/net';
31	import { DR_GATE_SWING } from '../drive/roadData';
32	import { drUseBody, DR_CAR_BODY, type DrBox } from '../drive/collide';
33	import { drBindDrop } from '../drive/keys';
34	import { drHudShow, drHudHide, drHudUpdate, type DrMapDot } from '../drive/hud';
35	import { drEnsureNet } from '../drive';
36	import { trNearby } from '../../common/trafficQuery';
37	import { exNightStep } from '../nightShows';
38	import { weatherU, shared } from '../../core/shared';
39	import { bkCreate, bkStep, bkRecover, bkSignal, bkPitch, BK_BODY, type BkState, type BkInput } from './motion';
40	import { bkInputFromKeys, BK_KEYS } from './keys';
41	import { BkBike, bkModelLoad, bkModelSetWarm, bkModelWarmAlso, type BkPlace } from './model';
42	import { BkRider, bkRiderLoad, type BkRiderSig } from './rider';
43	import { bkCamCreate, bkCamStep, bkCamPlace, bkCamDrag, bkCamSetEye, bkCamHideHead, type BkCam } from './camera';
44	import { BkDash } from './dash';
45	import { bkSound, bkRiverK, type BkSoundIn } from './sound';
46	import { bkFx, bkFxWarmObject, bkGrip, bkGustSteer } from './fx';
47	import { bkRoadSet } from './roadFx';
48	import { HR } from '../../bridges/han-tunnel/profile';
49	import { stChar } from '../stroll/char';
50	import type { SwingController } from '../../bridges/song-han/SwingController';
51	
52	/* Làm nóng shader của xe máy (D-018), như drive/index.ts drCarSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
53	   đèn / sương / bóng lấy từ cảnh chính, camera chính. Nhóm làm nóng (mô hình, mặt đồng hồ, hình tạm, tấm bóng) do model.ts dựng, không thêm vào scene */
54	bkModelSetWarm(async (o: THREE.Object3D) => {
55	  const rt = renderer.getRenderTarget();
56	  renderer.setRenderTarget(null);
57	  const a = renderer.compileAsync(o, camera, scene);
58	  renderer.setRenderTarget(rt);
59	  await a;
60	  renderer.setRenderTarget(composer.readBuffer);
61	  const b = renderer.compileAsync(o, camera, scene);
62	  renderer.setRenderTarget(rt);
63	  await b;
64	});
65	bkModelWarmAlso(bkFxWarmObject);   // vệt pha + bụi nước làm nóng cùng lượt với mô hình
66	
67	const BK_SOLO_SLOT = -1;   // bkCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot (trên Cầu Rồng, đi Đông, bên phải)
68	const C1 = CONFIG.bike.cam1;
69	const NO_DOTS: DrMapDot[] = [];   // lái một mình: bản đồ nhỏ không có xe người khác
70	
71	let net: DrNet | null = null;
72	let state: BkState | null = null;
73	let ctrl: SwingController | null = null;
74	let model: BkBike | null = null;   // hình xe của mình, dựng lần đầu vào chế độ
75	let rider: BkRider | null = null;  // người lái có xương (rider.ts); null khi nhân vật chưa nạp / nạp lỗi: xe không người (không hình tạm cho người)
76	let riderCh = -1;                  // nhân vật của rider hiện có (stChar)
77	let riderGen = 0;                  // tăng ở mỗi start() / stop(): kết quả nạp về muộn của lần trước bị bỏ
78	const _sig: BkRiderSig = { lean: 0, acc: 0, susF: 0, susR: 0, steer: 0 };   // tín hiệu người lái tái dùng mỗi khung
79	const bkKeys = new Set<string>();   // e.code đang giữ
80	const camB: BkCam = bkCamCreate();  // camera thứ nhất / thứ ba (camera.ts); view mặc định 1
81	let dash: BkDash | null = null;     // mặt đồng hồ canvas, dựng lần đầu vào chế độ
82	let motionK = C1.motion;            // hệ số chuyển động phụ: prefers-reduced-motion ⇒ motionReduced (đọc ở start())
83	let eyeFor: BkRider | null = null;  // người lái đã đo mắt góc thứ nhất (riderEye)
84	const _eye = new THREE.Vector3();
85	const _rest: BkPlace = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, lean: 0, steer: 0, wheel: 0, susF: 0, susR: 0, braking: false, sig: 0 };
86	const _sig0: BkRiderSig = { lean: 0, acc: 0, susF: 0, susR: 0, steer: 0 };
87	const _inp: BkInput = { gas: 0, brake: 0, steer: 0, hard: false, grip: 1 };   // đầu vào tái dùng mỗi khung
88	const boxes: DrBox[] = [];          // hộp xe tự động gần xe, tái dùng mỗi khung
89	let saved: { fov: number; near: number; explore: boolean } | null = null;   // thứ start() đổi, stop() trả lại
90	const _snd: BkSoundIn = { v: 0, rpm: 0, throttle: 0, brakeK: 0, sus: 0, sig: 0, rain: 0, tunnel: false, river: 0, view: 1, near: boxes, nNear: 0, x: 0, z: 0, yaw: 0, t: 0 };   // đầu vào âm thanh tái dùng mỗi khung
91	
92	const active = () => cam.mode === 'bike' && state !== null;
93	const inMode = () => active();     // chế độ xem (hết chỗ) ở Task 10
94	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
95	
96	/* Một bước: cổng nhịp quay, chuyển động (sơ tán nằm trong bkStep), hình xe, camera, HUD, hiệu ứng đêm */
97	function advance(dt: number, inp: BkInput): void {
98	  const s = state!, n = net!;
99	  if (ctrl) drSetGate(n, DR_GATE_SWING, ctrl.state !== 'CLOSED');
100	  const nNear = trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes);
101	  bkStep(s, inp, n, boxes, nNear, dt);
102	  model!.place(s);
103	  const tunnel = bkInTunnel(n, s), dry = tunnel && bkCovered(s);
104	  bkFx.update(s, shared.uNight.value, dry ? 0 : weatherU.uRain.value, dt, s.pitch, dry ? 0 : weatherU.uWet.value);
105	  riderStep(s, dt);
106	  riderEye();
107	  bkCamStep(camB, s, dt, motionK);
108	  if (bkCamPlace(camera, s, camB, n, dt)) onResize();   // fov / near đổi trong lúc trộn góc nhìn
109	  rider?.setFirstPerson(bkCamHideHead(camB));   // cùng giá trị trộn đã làm mượt mà camera dùng
110	  if (dash) { dash.bind(model!.dashMat); dash.update(dt, s.v, s.rpm, s.sig); }
111	  controls.target.set(s.x, s.y, s.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
112	  drHudUpdate(s, NO_DOTS);
113	  exNightStep(dt, false);
114	  soundStep(s, nNear, tunnel, dry);
115	}
116	
117	/* Âm thanh: điền BkSoundIn từ trạng thái xe (không cấp phát); bkSound tự giới hạn số lần ghi tham số (updateMs) */
118	function soundStep(s: BkState, nNear: number, tunnel: boolean, dry: boolean): void {
119	  _snd.v = s.v; _snd.rpm = s.rpm; _snd.throttle = s.throttle; _snd.brakeK = s.brakeK; _snd.sig = s.sig;
120	  _snd.sus = Math.max(Math.abs(s.susF), Math.abs(s.susR));
121	  _snd.rain = dry ? 0 : weatherU.uRain.value; _snd.tunnel = tunnel; _snd.river = bkRiverK(s.x);
122	  _snd.view = camB.view; _snd.nNear = nNear; _snd.x = s.x; _snd.z = s.z; _snd.yaw = s.yaw; _snd.t = shared.uTime.value;
123	  bkSound.update(_snd);
124	}
125	
126	/* Xe đang ở ô hầm không: ô chứa (x, z) có cao độ gần y nhất trong ± stepMax (như drive/net.ts drPadAt), kiểu 'tunnel'. Duyệt tuyến tính, không cấp phát */
127	function bkInTunnel(n: DrNet, s: BkState): boolean {
128	  const step = CONFIG.drive.stepMax;
129	  let best = -1, bestD = Infinity;
130	  for (let i = 0; i < n.pads.length; i++) {
131	    const p = n.pads[i];
132	    if (s.x < p.x0 || s.x > p.x1 || s.z < p.z0 || s.z > p.z1 || (p.gate !== undefined && n.closed.has(p.gate))) continue;
133	    const d = Math.abs(p.y(s.x, s.z) - s.y);
134	    if (d <= step && d < bestD) { best = i; bestD = d; }
135	  }
136	  return best >= 0 && n.pads[best].kind === 'tunnel';
137	}
138	/* Trong ô hầm thì đã ở đoạn có mái chưa (ngoài |x| > coverHalf là dốc hở: mưa, mặt ướt) */
139	const bkCovered = (s: BkState): boolean => Math.abs(s.x) <= HR.coverHalf;
140	
141	/* Người lái theo xe (sau model.place): tín hiệu từ trạng thái chuyển động */
142	function riderStep(s: BkState, dt: number): void {
143	  if (!rider || !model) return;
144	  _sig.lean = s.lean; _sig.acc = s.acc; _sig.susF = s.susF; _sig.susR = s.susR; _sig.steer = s.steer;
145	  rider.update(model, _sig, dt);
146	}
147	
148	/* Mắt góc thứ nhất theo người lái: đo một lần khi có người lái thật trên mô hình thật. Đặt xe về tư thế nghỉ (thẳng đứng, không lái, giảm xóc 0),
149	   người lái tư thế ngồi nền (lò xo phản ứng chưa chạy với người mới), giữa hai xương mắt (+ cam1.eyeFore; không có thì xương đầu + cam1.headEye)
150	   → hệ thân xe (nhóm ngoài: yaw · dốc, dốc = 0); rồi đặt lại như cũ */
151	function riderEye(): void {
152	  const s = state, r = rider, m = model;
153	  if (!r || !m || !m.real) { if (eyeFor) { eyeFor = null; bkCamSetEye(null); } return; }
154	  if (eyeFor === r || !s) return;
155	  eyeFor = r;
156	  _rest.x = s.x; _rest.y = s.y; _rest.z = s.z; _rest.yaw = s.yaw;
157	  m.place(_rest);
158	  r.update(m, _sig0, 0);
159	  r.setFirstPerson(false);
160	  const eyes = r.eyeLocal(m.group, _eye);
161	  bkCamSetEye(eyes ? { fore: _eye.x + C1.eyeFore, up: _eye.y } : { fore: _eye.x + C1.headEye.fore, up: _eye.y + C1.headEye.up });
162	  m.place(s);
163	  riderStep(s, 0);
164	}
165	
166	/* Nạp người lái theo nhân vật đã chọn (stChar, chung với Đi dạo). Về sau stop() / start() khác thì bỏ; nhân vật đổi thì thay người cũ */
167	function riderNeed(): void {
168	  const ch = stChar.get(), gen = ++riderGen;
169	  if (rider && riderCh === ch) return;
170	  void bkRiderLoad(ch).then((src) => {
171	    if (gen !== riderGen || state === null || !src) return;
172	    try {
173	      const r = new BkRider(src);
174	      rider?.dispose(); rider = r; riderCh = ch;
175	      riderStep(state, 0);
176	    } catch (e) { console.warn('Lái xe máy: không dựng được người lái', e); }
177	  });
178	}
179	
180	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới; y bỏ trống thì lấy mặt đường cao nhất tại đó. Cho test (__app.bike) và đặt lại vị trí */
181	function bkPlaceAt(x: number, z: number, yaw: number, y?: number): void {
182	  if (!net || !model) return;
183	  const s = bkCreate(net, BK_SOLO_SLOT);
184	  let gy = -Infinity;
185	  for (const p of net.pads) {
186	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
187	    gy = Math.max(gy, p.y(x, z));
188	  }
189	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
190	  bkPitch(s, net);
191	  state = s;
192	  bkCamReset();
193	  model.place(s);
194	  riderStep(s, 0);
195	  riderEye();
196	  if (bkCamPlace(camera, s, camB, net, 0, true)) onResize();
197	  controls.target.set(s.x, s.y, s.z);
198	}
199	
200	/* Trạng thái camera về đầu (giữ góc nhìn đang chọn, trộn xong ngay) */
201	function bkCamReset(): void {
202	  const v = camB.view;
203	  Object.assign(camB, bkCamCreate());
204	  camB.view = v; camB.mix = v === 3 ? 1 : 0;
205	}
206	
207	export const bike = {
208	  active,
209	  inMode,
210	  get state(): BkState | null { return state; },
211	  get net(): DrNet | null { return net; },
212	  get model(): BkBike | null { return model; },   // hình xe của mình (test: real, anchors)
213	  get rider(): BkRider | null { return rider; },  // người lái (test: debug(), setFirstPerson)
214	  get view(): 1 | 3 { return camB.view; },
215	  get cam(): BkCam { return camB; },               // test: mix, roll, bob, surge, yaw / pitch nhìn quanh
216	  get dash(): BkDash | null { return dash; },
217	  get cfg(): typeof CONFIG.bike { return CONFIG.bike; },   // test / kiểm tay: chỉnh số camera lúc chạy
218	  get sound(): typeof bkSound { return bkSound; },        // test: nodes(), on, graph
219	  get fx(): typeof bkFx { return bkFx; },                 // test: drawn() (vệt pha, số hạt bụi nước), group
220	  /* Đổi góc nhìn: trộn vị trí + hướng + fov + near trong cam1.mixS, không dừng xe */
221	  setView(v: 1 | 3): void { camB.view = v === 3 ? 3 : 1; },
222	  /* Vào lái một mình */
223	  start(): void {
224	    drUseBody(BK_BODY);
225	    const n = drEnsureNet();
226	    net = n;
227	    state = bkCreate(n, BK_SOLO_SLOT);
228	    camB.view = 1; bkCamReset();
229	    motionK = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches ? C1.motionReduced : C1.motion;
230	    if (!model) model = new BkBike();
231	    if (!dash) dash = new BkDash();
232	    scene.add(model.group);
233	    model.place(state);
234	    scene.add(bkFx.group); bkFx.start(n);
235	    bkRoadSet(true);                          // hạt nhựa + vệt ướt trên vật liệu đường (roadFx.ts; uRoadNear = 1 nếu CONFIG.bike.road.detail)
236	    riderNeed();
237	    riderStep(state, 0);
238	    driveView.far = CONFIG.drive.tunnelFar;   // mặt đường hầm hiện ở nút giao với hai đường dọc mới, như ô tô
239	    bkKeys.clear();
240	    drHudShow(n); bkSound.start();
241	    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
242	    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
243	    riderEye();
244	    bkCamPlace(camera, state, camB, n, 0, true); onResize();   // fov / near góc thứ nhất; onResize cập nhật ma trận chiếu và hệ số cỡ điểm
245	    controls.target.set(state.x, state.y, state.z);
246	    document.body.classList.add('explore', 'drive', 'bike');
247	  },
248	  update(dt: number): void {
249	    if (!active()) return;
250	    bkInputFromKeys(bkKeys, _inp);
251	    bkSound.horn(bkKeys.has('KeyH'));
252	    const s = state!, tun = bkInTunnel(net!, s) && bkCovered(s), wd = weatherU.uWindDir.value;
253	    _inp.grip = bkGrip(weatherU.uWet.value, tun);                                       // mặt ướt (trễ theo mưa); đoạn hầm kín luôn khô
254	    _inp.steer += bkGustSteer(s.v, weatherU.uGust.value, wd[0], wd[1], s.yaw);        // gió giật đẩy nhẹ độ nghiêng (≤ fx.gust.steer)
255	    advance(dt, _inp);
256	  },
257	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho mặt đồng hồ / chụp ảnh của task sau */
258	  afterRender(): void { /* chưa có việc */ },
259	  /* Rời chế độ: trả mọi thứ đã đổi, kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'bike' */
260	  stop(): void {
261	    if (state === null) return;
262	    state = null; bkKeys.clear(); riderGen++;
263	    bkSound.stop();
264	    rider?.setFirstPerson(false);
265	    drHudHide();
266	    model?.group.removeFromParent();
267	    bkFx.stop();
268	    bkRoadSet(false);                         // uRoadNear = 0: vật liệu đường về đúng ảnh cũ
269	    driveView.far = 1;
270	    drUseBody(DR_CAR_BODY);
271	    document.body.classList.remove('drive', 'bike');
272	    if (saved) {
273	      if (!saved.explore) document.body.classList.remove('explore');
274	      camera.fov = saved.fov; camera.near = saved.near; onResize();   // onResize tính lại ma trận chiếu theo fov / near cũ
275	      saved = null;
276	    }
277	    if (cam.mode === 'bike') { cam.mode = 'orbit'; controls.enabled = true; }
278	  },
279	  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
280	  step(dt: number, inp: BkInput): void { if (active()) advance(dt, inp); },
281	  placeAt: bkPlaceAt,
282	  /* Nạp mô hình thật (scooter.glb) và nhân vật người lái sớm, khi chọn thẻ Xe máy */
283	  preload(): void { void bkModelLoad(); void bkRiderLoad(stChar.get()); }
284	};
285	
286	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem (Task 10) */
287	export function setupBike(c: SwingController, onExit: () => void): void {
288	  ctrl = c; void onExit;
289	  window.addEventListener('keydown', (e) => {
290	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
291	    if (e.ctrlKey || e.metaKey || e.altKey) return;
292	    if (isField(e.target)) return;
293	    if (!BK_KEYS.has(e.code)) return;
294	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
295	    bkKeys.add(e.code);
296	    if (e.repeat) return;
297	    /* phím một lần (không theo giữ): về làn, xi nhan, góc nhìn */
298	    if (e.code === 'KeyR') bkRecover(state!, net!);
299	    else if (e.code === 'KeyQ') bkSignal(state!, 1);
300	    else if (e.code === 'KeyE') bkSignal(state!, -1);
301	    else if (e.code === 'KeyV') bike.setView(camB.view === 3 ? 1 : 3);
302	  });
303	  window.addEventListener('keyup', (e) => {
304	    bkKeys.delete(e.code);
305	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
306	  });
307	  const drop = drBindDrop(window, document, bkKeys);
308	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); bkSound.horn(false); } });
309	  window.addEventListener('blur', () => bkSound.horn(false));
310	  document.addEventListener('visibilitychange', () => { if (document.hidden) bkSound.horn(false); });
311	  bkSound.bind(document.getElementById('drSoundBtn'));   // nút 🔊 / 🔇 chung với ô tô: chỉ toggle tiếng xe máy khi đang lái xe máy
312	  /* Kéo chuột trái / vuốt (một ngón) trên canvas: nhìn quanh (góc thứ nhất) hoặc quay quanh xe (góc thứ ba) */
313	  let dragId = -1, lx = 0, ly = 0;
314	  canvas.addEventListener('pointerdown', (e) => {
315	    if (!active() || e.button !== 0 || dragId !== -1) return;
316	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
317	    canvas.setPointerCapture(e.pointerId);
318	  });
319	  canvas.addEventListener('pointermove', (e) => {
320	    if (e.pointerId !== dragId) return;
321	    bkCamDrag(camB, e.clientX - lx, e.clientY - ly);
322	    lx = e.clientX; ly = e.clientY;
323	  });
324	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
325	  canvas.addEventListener('pointerup', end);
326	  canvas.addEventListener('pointercancel', end);
327	  canvas.addEventListener('lostpointercapture', end);
328	}
