1	/* ============================ Lái xe: HUD (đồng hồ tốc độ, bản đồ nhỏ, gợi ý phím) ============================
2	   DOM + canvas 2D, không tốn lệnh vẽ 3D. Khung #drHud (index.html): #drSpeed / #drKmh (km/h), #drMap (canvas), #drMapNote (chú thích Hầm), #drHint.
3	   - Bản đồ nhỏ: Bắc (−Z) ở trên, Đông ở phải, không xoay. Nền (sông, đất, các ô mặt đường, năm công trình) vẽ MỘT lần vào canvas ẩn từ chính
4	     mạng đường DrNet (không lệch với đường lái được); mỗi lần cập nhật chỉ chép nền + chấm xe, tối đa CONFIG.drive.hud.mapMs một lần (10 lần/giây).
5	   - Hầm vượt sông Hàn là công trình chưa xây: ô hầm vẽ màu riêng và chú thích #drMapNote ghi "phương án đề xuất" (khóa drMapTunnel).
6	   - Đồng hồ: ghi DOM chỉ khi số km/h đổi; không tạo chuỗi / mảng mới khi giá trị hiển thị không đổi (D-018).
7	   - Gợi ý phím tự ẩn sau CONFIG.drive.hud.hintMs (chỉ hiện ở máy có chuột, CSS). Module không đụng DOM lúc import (test đơn vị chạy trong Node). */
8	import { CONFIG } from '../../config';
9	import { drBounds, type DrNet } from './net';
10	import type { DrState } from './motion';
11	
12	export interface DrMapDot { x: number; z: number; color: string }
13	type DrRect = { x0: number; x1: number; z0: number; z1: number };
14	
15	/* Chiếu (x, z) lên ô w × h px, một tỉ lệ cho cả hai trục: góc Tây Bắc (x0, z0) về (0, 0), Bắc (−Z) ở trên, Đông ở phải */
16	export function drMapProject(b: DrRect, w: number, h: number, x: number, z: number, out: { u: number; v: number }): void {
17	  const s = Math.min(w / (b.x1 - b.x0), h / (b.z1 - b.z0));
18	  out.u = (x - b.x0) * s; out.v = (z - b.z0) * s;
19	}
20	
21	/* km/h hiển thị của tốc độ v (m/s, có dấu): làm tròn |v| × 3,6 */
22	export function drKmh(v: number): number { return Math.round(Math.abs(v) * 3.6); }
23	
24	const H = CONFIG.drive.hud;
25	const _p = { u: 0, v: 0 };                                          // điểm chiếu tái dùng
26	let net: DrNet | null = null, bounds: DrRect | null = null;
27	let el: { root: HTMLElement | null; kmh: HTMLElement | null; map: HTMLCanvasElement | null; hint: HTMLElement | null } | null = null;
28	let bg: HTMLCanvasElement | null = null, bgNet: DrNet | null = null;   // nền bản đồ nhỏ và mạng đường nó vẽ từ
29	let ctx: CanvasRenderingContext2D | null = null;
30	let mw = 0, mh = 0;                                                  // cỡ canvas bản đồ (px)
31	let lastKmh = -1, lastMap = -1e9, hintTimer = 0;
32	
33	/* Nền bản đồ nhỏ: đất, sông (|x| < bankX), ô mặt đường theo loại, năm công trình. Vẽ lại khi đổi mạng hoặc cỡ */
34	function drMapBackdrop(n: DrNet, b: DrRect, w: number, h: number): HTMLCanvasElement {
35	  const c = document.createElement('canvas'); c.width = w; c.height = h;
36	  const g = c.getContext('2d')!, C = H.colors, p = _p;
37	  g.fillStyle = C.land; g.fillRect(0, 0, w, h);
38	  drMapProject(b, w, h, -CONFIG.bankX, b.z0, p); const u0 = p.u;
39	  drMapProject(b, w, h, CONFIG.bankX, b.z1, p);
40	  g.fillStyle = C.river; g.fillRect(u0, 0, p.u - u0, h);
41	  const s = Math.min(w / (b.x1 - b.x0), h / (b.z1 - b.z0));
42	  /* ô mặt đường: đường thường vẽ trước, cầu rồi hầm đè lên; nét tối thiểu roadMin px */
43	  for (const kind of ['road', 'junction', 'slip', 'bridge', 'tunnel'] as const) {
44	    g.fillStyle = kind === 'bridge' ? C.bridge : kind === 'tunnel' ? C.tunnel : C.road;
45	    for (const q of n.pads) {
46	      if (q.kind !== kind) continue;
47	      drMapProject(b, w, h, q.x0, q.z0, p);
48	      let uu = p.u, vv = p.v, ww = (q.x1 - q.x0) * s, hh = (q.z1 - q.z0) * s;
49	      if (ww < H.roadMin) { uu -= (H.roadMin - ww) / 2; ww = H.roadMin; }
50	      if (hh < H.roadMin) { vv -= (H.roadMin - hh) / 2; hh = H.roadMin; }
51	      g.fillRect(uu, vv, ww, hh);
52	    }
53	  }
54	  /* năm công trình: chấm ở giữa dòng sông (x = 0) tại z của từng công trình; Hầm cùng màu ô hầm (phương án đề xuất, ghi ở chú thích) */
55	  const marks: [number, string][] = [[CONFIG.songHan.z, C.mark], [0, C.mark], [CONFIG.tranThiLy.z, C.mark], [CONFIG.thuanPhuoc.z, C.mark], [CONFIG.hanTunnel.z, C.tunnel]];
56	  for (const [z, col] of marks) {
57	    drMapProject(b, w, h, 0, z, p);
58	    g.beginPath(); g.arc(p.u, p.v, 2.5, 0, Math.PI * 2); g.fillStyle = col; g.fill();
59	    g.lineWidth = 1; g.strokeStyle = C.edge; g.stroke();
60	  }
61	  g.strokeStyle = C.edge; g.lineWidth = 1; g.strokeRect(0.5, 0.5, w - 1, h - 1);
62	  return c;
63	}
64	
65	function drPlaceDot(x: number, z: number, r: number, col: string): void {
66	  drMapProject(bounds!, mw, mh, x, z, _p);
67	  ctx!.beginPath(); ctx!.arc(_p.u, _p.v, r, 0, Math.PI * 2); ctx!.fillStyle = col; ctx!.fill();
68	}
69	
70	/* Hiện HUD, dựng bản đồ nền theo mạng đường và cỡ màn hình (điện thoại nhỏ hơn); hẹn giờ ẩn gợi ý phím */
71	export function drHudShow(n: DrNet): void {
72	  if (!el) {
73	    const d = (id: string) => document.getElementById(id);
74	    el = { root: d('drHud'), kmh: d('drKmh'), map: d('drMap') as HTMLCanvasElement | null, hint: d('drHint') };
75	  }
76	  net = n;
77	  if (!bounds || bgNet !== n) { const b = drBounds(n); bounds = { x0: b.x0, x1: b.x1, z0: b.z0, z1: b.z1 }; }
78	  const touch = typeof window.matchMedia === 'function' && window.matchMedia('(hover: none)').matches;
79	  const edge = touch ? H.mapTouch : H.mapDesk, bw = bounds.x1 - bounds.x0, bh = bounds.z1 - bounds.z0;
80	  const nw = Math.max(1, Math.round(edge * Math.min(1, bw / bh))), nh = Math.max(1, Math.round(edge * Math.min(1, bh / bw)));
81	  if (el.map) {
82	    if (nw !== mw || nh !== mh || bgNet !== n) { mw = nw; mh = nh; el.map.width = mw; el.map.height = mh; if (el.root) el.root.style.setProperty('--dr-map-h', mh + 'px'); bg = drMapBackdrop(n, bounds, mw, mh); bgNet = n; }
83	    ctx = el.map.getContext('2d');
84	  }
85	  lastKmh = -1; lastMap = -1e9;
86	  if (el.hint) el.hint.classList.remove('off');
87	  window.clearTimeout(hintTimer);
88	  hintTimer = window.setTimeout(() => { if (el && el.hint) el.hint.classList.add('off'); }, H.hintMs);
89	}
90	
91	export function drHudHide(): void {
92	  window.clearTimeout(hintTimer);
93	  net = null; ctx = null;
94	}
95	
96	/* Mỗi khung: số km/h (ghi DOM khi đổi), bản đồ nhỏ (tối đa mapMs một lần); others: xe người khác (exDrivers.dots) */
97	export function drHudUpdate(s: Pick<DrState, 'x' | 'z' | 'yaw' | 'v'>, others: DrMapDot[]): void {
98	  if (!el || !net) return;
99	  const k = drKmh(s.v);
100	  if (k !== lastKmh) { lastKmh = k; if (el.kmh) el.kmh.textContent = String(k); }
101	  const now = performance.now();
102	  if (!ctx || !bg || !bounds || now - lastMap < H.mapMs) return;
103	  lastMap = now;
104	  ctx.drawImage(bg, 0, 0);
105	  for (let i = 0; i < others.length; i++) drPlaceDot(others[i].x, others[i].z, H.otherR, others[i].color);
106	  /* xe của mình: mũi tên hướng xe (tiến = (cos yaw, −sin yaw) trên (x, z), cũng là hướng (u, v) vì bản đồ không xoay) */
107	  drMapProject(bounds, mw, mh, s.x, s.z, _p);
108	  const fx = Math.cos(s.yaw), fz = -Math.sin(s.yaw), R = H.meR;
109	  ctx.beginPath();
110	  ctx.moveTo(_p.u + fx * R * 1.5, _p.v + fz * R * 1.5);
111	  ctx.lineTo(_p.u - fx * R + fz * R * 0.9, _p.v - fz * R - fx * R * 0.9);
112	  ctx.lineTo(_p.u - fx * R - fz * R * 0.9, _p.v - fz * R + fx * R * 0.9);
113	  ctx.closePath(); ctx.fillStyle = H.colors.me; ctx.fill();
114	  ctx.lineWidth = 1; ctx.strokeStyle = 'rgba(0,0,0,.6)'; ctx.stroke();
115	}
