1	/* ============================ Lái xe máy: đầu vào từ bàn phím (thuần) ============================
2	   Theo vị trí vật lý (e.code), như drive/keys.ts: bố cục không Latin vẫn dùng WASD.
3	   W/↑ ga, S/↓ phanh (đứng yên: dắt lùi, motion.ts lo), A/← nghiêng trái (steer +1), D/→ nghiêng phải (steer −1), hai phím trái phải triệt nhau; Space phanh gấp.
4	   H còi, V đổi góc nhìn, Q / E xi nhan trái / phải, R về làn: không thuộc BkInput, index.ts đọc tập phím. grip không ghi ở đây (index.ts đặt theo thời tiết).
5	   Không cấp phát (gọi mỗi khung). */
6	import type { BkInput } from './motion';
7	
8	/* Các e.code chế độ xe máy ghi vào tập phím (index.ts chặn hành vi mặc định của mũi tên và Space) */
9	export const BK_KEYS = new Set(['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space', 'KeyH', 'KeyV', 'KeyQ', 'KeyE', 'KeyR']);
