body.drive #drSoundBtn:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
@media (hover:none){
  body.drive:not(.ex-watching) #drSoundBtn{left:calc(16px + env(safe-area-inset-left,0px));transform:none;bottom:calc(36px + var(--dr-pad-h,72px) + env(safe-area-inset-bottom,0px));}
}
body.drive #scene{cursor:grab;}
body.drive #scene:active{cursor:grabbing;}
/* Cảm ứng (hover:none): ngón trái cần gạt ngang dưới trái; ngón phải GA (to) và PHANH (nhỏ hơn, bên trái GA) dưới phải; vuốt vùng trống xoay camera.
   Kích thước từ CONFIG.drive.touch qua biến --dr-*; màn hẹp co theo bề rộng để ba nút không chồng nhau ở 390 px. Bản đồ nhỏ lên trái dưới hàng nút ⚙ / Thoát, đồng hồ giữa trên (đáy dành cho điều khiển) */
@media (hover:none){
  body.drive #drLook{display:block;position:fixed;pointer-events:auto;touch-action:none;left:0;right:0;bottom:0;top:calc(56px + env(safe-area-inset-top,0px));}
  body.drive #drSteer{display:block;position:fixed;pointer-events:auto;touch-action:none;left:calc(16px + env(safe-area-inset-left,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:min(var(--dr-pad-w,180px),38vw);height:var(--dr-pad-h,72px);box-sizing:border-box;border-radius:999px;background:rgba(10,18,22,.4);border:2px solid var(--panel-line);}
  #drKnob{position:absolute;left:50%;top:50%;width:var(--dr-knob,56px);height:var(--dr-knob,56px);margin:calc(var(--dr-knob,56px) / -2) 0 0 calc(var(--dr-knob,56px) / -2);border-radius:50%;background:rgba(230,189,106,.55);border:1px solid var(--gold);pointer-events:none;}
  body.drive #drGas,body.drive #drBrake{display:flex;align-items:center;justify-content:center;position:fixed;pointer-events:auto;touch-action:none;margin:0;padding:0;box-sizing:border-box;color:var(--text);background:rgba(10,18,22,.5);border:2px solid var(--panel-line);border-radius:18px;font:700 14px/1.1 var(--font-body);text-align:center;cursor:pointer;-webkit-tap-highlight-color:transparent;}
  body.drive #drGas{right:calc(16px + env(safe-area-inset-right,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:min(var(--dr-gas-w,92px),24vw);height:var(--dr-gas-h,124px);}
  body.drive #drBrake{right:calc(26px + min(var(--dr-gas-w,92px),24vw) + env(safe-area-inset-right,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:min(var(--dr-brake-w,76px),19vw);height:var(--dr-brake-h,84px);}
  body.drive #drGas.on{background:rgba(230,189,106,.6);border-color:var(--gold);}
  body.drive #drBrake.on{background:rgba(214,70,60,.6);border-color:#e86a5e;}
  body.drive #drMap{left:calc(8px + env(safe-area-inset-left,0px));top:calc(56px + env(safe-area-inset-top,0px));bottom:auto;}   /* dưới hàng nút ⚙ / Thoát (hai góc trên; ar đổi chỗ hai nút) */
  body.drive #drMapNote{left:calc(8px + env(safe-area-inset-left,0px));top:calc(60px + var(--dr-map-h,128px) + env(safe-area-inset-top,0px));bottom:auto;font-size:10px;max-width:calc(50vw - 24px);}
  body.drive #drSpeed{right:auto;bottom:auto;left:50%;transform:translateX(-50%);top:calc(8px + env(safe-area-inset-top,0px));}
}
/* Xe máy (body.explore.drive.bike): dùng nguyên khung #drHud của ô tô (đồng hồ, bản đồ nhỏ, gợi ý); nút 🔊 #drSoundBtn hiện như ô tô, bấm thì bật / tắt tiếng xe máy (bike/sound.ts).
   Điều khiển cảm ứng của ô tô điều khiển ô tô, ẩn tới khi xe máy có phần cảm ứng riêng */
body.bike #drSteer,body.bike #drGas,body.bike #drBrake,body.bike #drLook{display:none !important;}
/* Dòng hướng dẫn phím của đi dạo (#stHint): cùng chỗ và kiểu với #exHint, chỉ khi có chuột (hover:hover) và không ở chế độ xem; cảm ứng đã có cần gạt */
#stHint{display:none;}
@media (hover:hover){
  body.explore.stroll:not(.ex-watching) #stHint{display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);text-align:center;max-width:calc(100vw - 200px);box-sizing:border-box;pointer-events:none;z-index:4;}
  body.compact.stroll #stHint{top:calc(64px + env(safe-area-inset-top,0px));}
}
body.stroll #scene{cursor:grab;}
body.stroll #scene:active{cursor:grabbing;}
/* Đi dạo: điều khiển cảm ứng (explore/stroll/touch.ts). #stHud là lớp phủ trong suốt, chỉ các điều khiển nhận chạm; direction:ltr để ar (RTL) vẫn giữ cần gạt bên trái tay.
   Bố cục B: cần gạt trái dưới; phải chỉ 📷; vuốt nửa phải để xoay camera. Cần gạt, vuốt chỉ hiện khi không có chuột (hover:none); 📷 hiện cả trên máy tính */
#stHud,#stPad,#stLook,#stPhoto,#stFlash{display:none;}
body.stroll #stHud{display:block;position:fixed;inset:0;z-index:4;pointer-events:none;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;}

