16	   Mỗi khung không cấp phát (D-018). */
17	import * as THREE from 'three';
18	import { CONFIG } from '../../config';
19	import { rng } from '../../common/math';
20	import { drGround, type DrNet } from '../drive/net';
21	import type { BkState } from './motion';
22	
23	const FB = CONFIG.bike.fx.beam, FS = CONFIG.bike.fx.spray, FG = CONFIG.bike.fx.gust, P = CONFIG.bike.perf, L = CONFIG.bike.body.wheelbase, LOCK = CONFIG.bike.model.steerLock;
24	const fin = (v: number, d = 0): number => (Number.isFinite(v) ? v : d);
25	const clamp01 = (v: number): number => (v < 0 ? 0 : v > 1 ? 1 : v);
26	
27	/* ===== Hàm thuần ===== */
28	export function bkGrip(wet: number, inTunnel: boolean): number {
29	  if (inTunnel) return 1;
30	  return 1 - clamp01(fin(wet));
31	}
32	
33	export function bkGustSteer(v: number, gust: number, wdx: number, wdz: number, yaw: number): number {
34	  if (!(fin(v) > P.vBlend)) return 0;
35	  const g = clamp01(fin(gust) / FG.ref);
36	  if (g === 0) return 0;
37	  /* bên trái thân xe: (−sin yaw, −cos yaw) (mũi (cos yaw, −sin yaw), trục Y lên) */
38	  const side = -fin(wdx) * Math.sin(yaw) - fin(wdz) * Math.cos(yaw);
39	  return FG.steer * g * (side > 1 ? 1 : side < -1 ? -1 : side);
40	}
41	
42	/* ===== Vệt đèn pha ===== */
43	const ROWS = FB.rows, NB = 2 * (ROWS + 1);
44	
45	/* Texture quạt: u ngang (0..1), v dọc (0 gần xe .. 1 xa); độ sáng ghi vào RGB (cộng màu nhân alpha = 1), hẹp ở gần, mở theo căn bậc hai, tắt dần ở xa, đốm sáng ở ≈ 0,3 */
46	function beamTexture(): THREE.DataTexture {
47	  const n = FB.px, d = new Uint8Array(n * n * 4);
48	  let mx = 0;
49	  const f = new Float32Array(n * n);
50	  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
51	    const u = (x + 0.5) / n, v = (y + 0.5) / n;
52	    const half = 0.22 + 0.78 * Math.sqrt(v), e = Math.abs(u - 0.5) * 2 / half, across = e >= 1 ? 0 : 1 - e * e;   // quạt mở nhanh ở gần xe
53	    const rise = Math.min(1, v / 0.06), along = rise * rise * (3 - 2 * rise) * Math.pow(1 - v, 1.1) * (0.7 + 0.3 * Math.exp(-(((v - 0.3) / 0.2) ** 2)));
54	    f[y * n + x] = across * along; mx = Math.max(mx, across * along);
55	  }
56	  for (let i = 0; i < n * n; i++) { const c = Math.round(255 * f[i] / mx); d[i * 4] = c; d[i * 4 + 1] = c; d[i * 4 + 2] = c; d[i * 4 + 3] = 255; }
57	  const t = new THREE.DataTexture(d, n, n, THREE.RGBAFormat);
58	  t.magFilter = THREE.LinearFilter; t.minFilter = THREE.LinearFilter; t.needsUpdate = true;
59	  return t;
60	}
61	
62	function beamGeometry(): THREE.BufferGeometry {
63	  const g = new THREE.BufferGeometry(), uv = new Float32Array(NB * 2), idx: number[] = [];
64	  for (let j = 0; j <= ROWS; j++) {
65	    uv[j * 4] = 0; uv[j * 4 + 1] = j / ROWS; uv[j * 4 + 2] = 1; uv[j * 4 + 3] = j / ROWS;
66	    if (j < ROWS) { const a = 2 * j, b = a + 1, c = a + 2, e = a + 3; idx.push(a, b, c, b, e, c); }   // mặt nhìn từ trên (pháp tuyến +Y; u = 0 là bên trái xe)
67	  }
68	  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(NB * 3), 3).setUsage(THREE.DynamicDrawUsage));
69	  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
70	  g.setIndex(idx);
71	  return g;
72	}
73	
74	const beamMat = new THREE.MeshBasicMaterial({ color: FB.color, map: beamTexture(), transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false,
75	  polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -4, fog: false });
76	beamMat.name = 'bikeBeam';
77	const beam = new THREE.Mesh(beamGeometry(), beamMat);
78	beam.name = 'bike-beam';
79	
80	/* ===== Bụi nước ===== */
81	const MAX = FS.max;
82	function dotTexture(): THREE.DataTexture {
83	  const n = 32, d = new Uint8Array(n * n * 4);
84	  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
85	    const u = (x + 0.5) / n * 2 - 1, v = (y + 0.5) / n * 2 - 1, r = Math.hypot(u, v), a = r >= 1 ? 0 : (1 - r * r) ** 2;
86	    const i = (y * n + x) * 4; d[i] = 255; d[i + 1] = 255; d[i + 2] = 255; d[i + 3] = Math.round(255 * a);
87	  }
88	  const t = new THREE.DataTexture(d, n, n, THREE.RGBAFormat);
89	  t.magFilter = THREE.LinearFilter; t.minFilter = THREE.LinearFilter; t.needsUpdate = true;
90	  return t;
91	}
92	const sPos = new Float32Array(MAX * 3), sCol = new Float32Array(MAX * 4), sVel = new Float32Array(MAX * 3), sAge = new Float32Array(MAX), sGround = new Float32Array(MAX);
93	const sprayGeo = new THREE.BufferGeometry();
94	sprayGeo.setAttribute('position', new THREE.BufferAttribute(sPos, 3).setUsage(THREE.DynamicDrawUsage));
95	sprayGeo.setAttribute('color', new THREE.BufferAttribute(sCol, 4).setUsage(THREE.DynamicDrawUsage));
96	sprayGeo.setDrawRange(0, 0);
97	const sprayMat = new THREE.PointsMaterial({ size: FS.size, sizeAttenuation: true, map: dotTexture(), vertexColors: true, transparent: true, opacity: FS.opacity, depthWrite: false });
98	sprayMat.name = 'bikeSpray';
99	const spray = new THREE.Points(sprayGeo, sprayMat);
100	spray.name = 'bike-spray';
101	const sprayBase = new THREE.Color(FS.color);
102	
103	for (const o of [beam, spray] as THREE.Object3D[]) { o.layers.set(1); o.castShadow = false; o.receiveShadow = false; o.frustumCulled = false; o.visible = false; o.renderOrder = 1; }
104	
105	const group = new THREE.Group();
106	group.name = 'bike-fx';
107	group.add(beam, spray);
108	
109	let net: DrNet | null = null;
110	let rnd: () => number = rng(FS.seed);
111	let nAlive = 0, emit = 0;
112	
113	/* Vệt pha: đặt đỉnh theo xe + mặt đường; ẩn khi chưa đủ tối */
114	function beamStep(s: BkState, night: number, pitch: number, wet: number): void {
115	  const nt = fin(night);
116	  if (!(nt > FB.nightMin)) { beam.visible = false; return; }
117	  const w = clamp01(fin(wet)), gain = 1 + (FB.wetGain - 1) * w;
118	  const k = clamp01((nt - FB.nightMin) / (1 - FB.nightMin)), kk = k * k * (3 - 2 * k);
119	  beamMat.opacity = Math.min(1, FB.opacity * kk * gain);
120	  const st = fin(s.steer), h = fin(s.yaw) + (st > LOCK ? LOCK : st < -LOCK ? -LOCK : st);
121	  const fx = Math.cos(h), fz = -Math.sin(h), lx = -Math.sin(h), lz = -Math.cos(h), hw = FB.width / 2, len = FB.len * gain, tp = Math.tan(fin(pitch));
122	  const x0 = fin(s.x), y0 = fin(s.y), z0 = fin(s.z);
123	  const a = beam.geometry.getAttribute('position') as THREE.BufferAttribute, p = a.array as Float32Array;
124	  /* mỗi mép dò dần theo hàng: tầng mặt đường tìm quanh cao độ hàng trước + dốc (dốc cong lên / xuống vẫn bám, không nhảy sang tầng khác) */
125	  for (let c = 0; c < 2; c++) {
126	    const sd = c === 0 ? hw : -hw;
127	    let yPrev = y0, dPrev = 0;
128	    for (let j = 0; j <= ROWS; j++) {
129	      const d = FB.ahead + len * j / ROWS, x = x0 + fx * d + lx * sd, z = z0 + fz * d + lz * sd, yRef = yPrev + tp * (d - dPrev);
130	      const g = net ? drGround(net, x, z, yRef) : NaN, y = Number.isFinite(g) ? g : yRef, i = (2 * j + c) * 3;
131	      p[i] = x; p[i + 1] = y + FB.lift; p[i + 2] = z;
132	      yPrev = y; dPrev = d;
133	    }
134	  }
135	  a.needsUpdate = true;
136	  beam.visible = true;
137	}
138	
139	/* Bụi nước: hạt cũ bay + hết đời (dồn về đầu mảng), sinh hạt mới ở hai bánh */
140	function sprayStep(s: BkState, night: number, rain: number, dt: number): void {
141	  const v = fin(s.v), r = clamp01(fin(rain));
142	  /* hạt cũ */
143	  for (let i = 0; i < nAlive;) {
144	    sAge[i] += dt;
145	    if (sAge[i] >= FS.life) {
146	      const j = --nAlive;
147	      if (i !== j) { sPos[i * 3] = sPos[j * 3]; sPos[i * 3 + 1] = sPos[j * 3 + 1]; sPos[i * 3 + 2] = sPos[j * 3 + 2]; sVel[i * 3] = sVel[j * 3]; sVel[i * 3 + 1] = sVel[j * 3 + 1]; sVel[i * 3 + 2] = sVel[j * 3 + 2]; sAge[i] = sAge[j]; sGround[i] = sGround[j]; }
148	      continue;
149	    }
150	    sVel[i * 3 + 1] -= FS.gravity * dt;
151	    sPos[i * 3] += sVel[i * 3] * dt; sPos[i * 3 + 1] += sVel[i * 3 + 1] * dt; sPos[i * 3 + 2] += sVel[i * 3 + 2] * dt;
152	    if (sPos[i * 3 + 1] < sGround[i]) { sPos[i * 3 + 1] = sGround[i]; sVel[i * 3 + 1] = 0; sVel[i * 3] *= 0.5; sVel[i * 3 + 2] *= 0.5; }
153	    i++;
154	  }
155	  /* hạt mới */
156	  const kv = clamp01((Math.abs(v) - FS.vMin) / (FS.vFull - FS.vMin)), rate = MAX / FS.life * r * kv;
157	  if (rate > 0 && Math.abs(v) > FS.vMin) {
158	    emit += rate * dt;
159	    const yaw = fin(s.yaw), fx = Math.cos(yaw), fz = -Math.sin(yaw), lx = -Math.sin(yaw), lz = -Math.cos(yaw), sg = v < 0 ? -1 : 1;
160	    const x0 = fin(s.x), y0 = fin(s.y), z0 = fin(s.z);
161	    while (emit >= 1 && nAlive < MAX) {
162	      emit -= 1;
163	      const i = nAlive++, rear = rnd() < FS.rearK, ax = (rear ? -L / 2 : L / 2) - 0.25 * sg, lat = (rnd() * 2 - 1) * 0.08;
164	      sPos[i * 3] = x0 + fx * ax + lx * lat; sPos[i * 3 + 1] = y0 + 0.05; sPos[i * 3 + 2] = z0 + fz * ax + lz * lat;
165	      const fwd = v * FS.carry * (0.8 + 0.4 * rnd()), up = FS.up[0] + (FS.up[1] - FS.up[0]) * rnd(), side = (rnd() * 2 - 1) * FS.side;
166	      sVel[i * 3] = fx * fwd + lx * side; sVel[i * 3 + 1] = up; sVel[i * 3 + 2] = fz * fwd + lz * side;
167	      const age = rnd() * dt;   // sinh rải trong khung: không thành từng lớp
168	      sAge[i] = age; sGround[i] = y0;
169	      sPos[i * 3] += sVel[i * 3] * age; sPos[i * 3 + 1] += sVel[i * 3 + 1] * age; sPos[i * 3 + 2] += sVel[i * 3 + 2] * age;
170	    }
171	    if (nAlive >= MAX) emit = 0;
172	  } else emit = 0;
173	  /* màu: tối về đêm, mờ dần theo đời */
174	  const dim = 1 - (1 - FS.nightDim) * clamp01(fin(night)), cr = sprayBase.r * dim, cg = sprayBase.g * dim, cb = sprayBase.b * dim;
175	  for (let i = 0; i < nAlive; i++) { const t = 1 - sAge[i] / FS.life; sCol[i * 4] = cr; sCol[i * 4 + 1] = cg; sCol[i * 4 + 2] = cb; sCol[i * 4 + 3] = t > 0 ? t : 0; }
176	  sprayGeo.setDrawRange(0, nAlive);
177	  if (nAlive > 0) { (sprayGeo.getAttribute('position') as THREE.BufferAttribute).needsUpdate = true; (sprayGeo.getAttribute('color') as THREE.BufferAttribute).needsUpdate = true; }
178	  spray.visible = nAlive > 0;
179	}
180	
181	function reset(): void {
182	  nAlive = 0; emit = 0; rnd = rng(FS.seed);
183	  sprayGeo.setDrawRange(0, 0);
184	  beam.visible = false; spray.visible = false;
185	}
186	
187	export const bkFx = {
188	  group,
189	  /* Vào chế độ: hạt về 0, rng tạo lại (tất định); net cho cao độ mặt đường của vệt pha (không có thì theo pitch) */
190	  start(n?: DrNet | null): void { net = n ?? null; reset(); },
191	  /* Rời chế độ: gỡ nhóm khỏi cảnh, ẩn hết */
192	  stop(): void { group.removeFromParent(); reset(); net = null; },
193	  /* Một khung, sau model.place: night = shared.uNight; rain 0..1 (0 trong hầm); pitch rad dốc xe (mặt phẳng dự phòng); wet 0..1 mặt ướt (0 trong hầm) */
194	  update(s: BkState, night: number, rain: number, dt: number, pitch: number, wet = 0): void {
195	    const d = Number.isFinite(dt) && dt > 0 ? Math.min(dt, 0.1) : 0;
196	    beamStep(s, night, pitch, wet);
197	    if (d > 0) sprayStep(s, night, rain, d);
198	  },
199	  drawn(): { beam: boolean; spray: number } { return { beam: beam.visible, spray: spray.visible ? nAlive : 0 }; }
200	};
201	
202	/* Nhóm tạm để làm nóng shader (model.ts): lưới mới dùng chung hình học + vật liệu thật, luôn hiện */
203	export function bkFxWarmObject(): THREE.Object3D {
204	  const g = new THREE.Group();
205	  g.add(new THREE.Mesh(beam.geometry, beamMat), new THREE.Points(sprayGeo, sprayMat));
206	  return g;
207	}
208

