      up: [1.0, 2.4] as [number, number],   // m/s — vận tốc bắn lên nhỏ nhất, lớn nhất (ước lượng)
      side: 0.8,       // m/s — vận tốc bắn ngang lớn nhất mỗi bên (ước lượng)
