// Ảnh kiểm tay HUD xe máy: node shot.mjs <tên> [mobile] [wx]
import { createRequire } from 'node:module';
const require = createRequire('D:/2026 - Tuan/danang-vite-xe-may/package.json');
const { chromium } = require('playwright');
const name = process.argv[2] || 'bike-hud';
const mobile = process.argv.includes('mobile');
const wx = process.argv.find((a) => a.startsWith('wx='))?.slice(3);
const extra = process.argv.find((a) => a.startsWith('js='))?.slice(3);
const browser = await chromium.launch({ args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const ctx = mobile ? await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 }) : await browser.newContext({ viewport: { width: 1280, height: 720 } });
const page = await ctx.newPage();
page.setDefaultTimeout(400000);
const errs = [];
page.on('pageerror', (e) => errs.push('pageerror ' + e));
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errs.push(m.type() + ' ' + m.text()); });
await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
const t0 = Date.now();
await page.goto('http://localhost:5199/?test&explore=bike' + (wx ? '&wx=' + wx : ''), { waitUntil: 'load', timeout: 400000 });
await page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done') && window.__app.bike?.active(), null, { timeout: 400000 });
console.log('loaded', (Date.now() - t0) / 1000);
await page.waitForFunction(() => window.__app.bike.model?.real, null, { timeout: 200000 }).catch(() => console.log('no real model'));
if (extra) { const r = await page.evaluate(extra); console.log('js:', JSON.stringify(r)); }
await page.evaluate(() => new Promise((ok) => { let i = 0; const f = () => (++i >= 3 ? ok() : requestAnimationFrame(f)); requestAnimationFrame(f); }));
await page.screenshot({ path: `D:/2026 - Tuan/danang-vite-xe-may/tests/screens/${name}.png` });
const info = await page.evaluate(() => {
  const r = (id) => { const e = document.getElementById(id); if (!e) return null; const b = e.getBoundingClientRect(); const cs = getComputedStyle(e); return cs.display === 'none' ? 'none' : [Math.round(b.left), Math.round(b.top), Math.round(b.width), Math.round(b.height)].join(','); };
  const o = {};
  for (const id of ['drSoundBtn', 'drSpeed', 'drMap', 'drMapNote', 'drHint', 'drSteer', 'drGas', 'drBrake', 'drLook', 'bkSigL', 'bkSigR', 'bkView', 'bkHorn', 'bkReset', 'bkHint', 'bkStuck', 'btnExExit']) o[id] = r(id);
  o.brand = [...document.querySelectorAll('button')].filter((b) => b.offsetParent && getComputedStyle(b).position === 'fixed').map((b) => (b.id || b.className) + ':' + JSON.stringify(b.getBoundingClientRect().toJSON()));
  return o;
});
console.log(JSON.stringify(info, null, 1));
console.log(errs.slice(0, 20).join('\n'));
await browser.close();

