console.log('real', await page.evaluate(() => window.__app.bike.model.real), (Date.now() - t0) / 1000, 's');
const wait = (ms) => page.waitForTimeout(ms);
const info = () => page.evaluate(() => { const b = window.__app.bike, m = b.model, a = m.anchors; const v = new window.__app.THREE.Vector3();
  const w = (o) => o.getWorldPosition(v).toArray().map((x) => +x.toFixed(3));
  return { s: { x: +b.state.x.toFixed(2), y: +b.state.y.toFixed(3), z: +b.state.z.toFixed(2), yaw: +b.state.yaw.toFixed(3), lean: +b.state.lean.toFixed(3), steer: +b.state.steer.toFixed(3), v: +b.state.v.toFixed(2) }, grip: w(a.gripL), seat: w(a.seat), eye: w(a.eye), calls: window.__app.renderer.info.render.calls }; });
await wait(3000);
console.log('ngay', JSON.stringify(await info()));
await page.screenshot({ path: OUT + 'bike-model.png' });
/* cận cảnh: tạm dừng camera lái (cam.mode khác 'bike'), đặt camera bên trái xe */
const close = async (name, dx, dy, dz) => {
  await page.evaluate(([dx, dy, dz]) => { const A = window.__app, s = A.bike.state; A.cam.mode = 'frozen'; A.controls.minDistance = 0.3; A.controls.target.set(s.x, s.y + 0.7, s.z);
    const c = Math.cos(s.yaw), sn = Math.sin(s.yaw);   // tiến (c, −sn), trái (−sn, −c)
    A.camera.position.set(s.x + dx * c - dz * sn, s.y + dy, s.z - dx * sn - dz * c); A.camera.lookAt(s.x, s.y + 0.7, s.z); }, [dx, dy, dz]);
  await wait(2500); await page.screenshot({ path: OUT + name });
  await page.evaluate(() => { window.__app.cam.mode = 'bike'; window.__app.controls.minDistance = 8; });
};
