416	  // Mục 7 — Lái xe trên điện thoại (D-034 Task 9): mở bằng thẻ Ô tô ở màn chọn cảm ứng
417	  const CD = await openApp(browser, srv.url + '?chooser', { width: 844, height: 390, mobile: true });
418	  CD.page.setDefaultTimeout(180000);
419	  await CD.page.waitForFunction(() => !document.getElementById('chooser').hidden);
420	  check('màn chọn cảm ứng: thẻ Ô tô không khóa', await CD.page.evaluate(() => !document.querySelector('[data-pick="car"]').disabled));
421	  await CD.page.tap('[data-pick="car"]');
422	  await CD.page.waitForFunction(() => document.body.classList.contains('drive') && window.__app.cam.mode === 'car' && window.__app.drive.state);
423	  check('chạm thẻ Ô tô vào được chế độ lái (body.drive, cam.mode car)', true);
424	  const DH = ['#drSteer', '#drGas', '#drBrake'];
425	  /* Danh sách người chơi giả đầy nhất (đầu + 5 người lái) để thử chồng lấn ở chỗ xấu nhất; không đổi trạng thái chế độ */
426	  const fillDriveRoster = (page) => page.evaluate(() => {
427	    const r = document.getElementById('exMpRoster');
428	    r.innerHTML = '<div class="ex-mp-head">Вождение 5/5 · Прогулка 5/5 · Полёт 5/5 (наблюдение)</div>' + Array.from({ length: 5 }, (_, i) => `<div class="ex-mp-row drive"><i></i>Tài xế ${i}</div>`).join('');
429	    r.hidden = false;
430	    /* hai thông báo chuỗi dài tiếng Nga: phải không đè danh sách / bản đồ nhỏ */
431	    const n = document.getElementById('exMpNotice'), idle = document.getElementById('exMpIdle');
432	    n.textContent = 'Игрок вышел из игры, освободилось место для вас'; n.hidden = false;
433	    idle.textContent = 'Вы будете отключены через 15 секунд из-за бездействия'; idle.hidden = false;
434	  });
435	  const driveLayout = async (page, W, H, tag) => {
436	    await fillDriveRoster(page); await frames(page, 2);
437	    const hud = await rects(page, DH), avoid = await rects(page, ['#btnExExit', '#drMap', '#drSpeed', '#exMpRoster', '#exMpNotice', '#exMpIdle', '#drSoundBtn']);
438	    const snd = avoid.find((b) => b.sel === '#drSoundBtn');   // nút tiếng xe 🔊 / 🔇 (sửa cuối D-034)
439	    check(`lái xe ${tag}: cần gạt, GA, PHANH hiện`, hud.length === 3);
440	    check(`lái xe ${tag}: mỗi nút ≥ 44 × 44 px (cả nút tiếng xe)`, hud.every((b) => b.width >= 44 && b.height >= 44) && !!snd && snd.width >= 44 && snd.height >= 44);
441	    check(`lái xe ${tag}: nằm trọn trong khung nhìn (cả nút tiếng xe)`, [...hud, ...(snd ? [snd] : [])].every((b) => b.left >= 0 && b.top >= 0 && b.right <= W && b.bottom <= H));
442	    check(`lái xe ${tag}: ba điều khiển + nút tiếng xe không chồng nhau và không chồng Thoát / bản đồ nhỏ / đồng hồ / danh sách người chơi / hai thông báo`, avoid.length === 7 && noOverlap([...hud, ...avoid]));
443	    check(`lái xe ${tag}: nút tiếng xe không bị lớp khác che, có aria-label, aria-pressed`, (await topAtCenter(page, '#drSoundBtn')) && (await page.evaluate(() => { const b = document.getElementById('drSoundBtn'); return !!b.getAttribute('aria-label') && ['true', 'false'].includes(b.getAttribute('aria-pressed')); })));
444	    check(`lái xe ${tag}: danh sách người chơi nằm trọn trong khung nhìn`, avoid.filter((b) => b.sel === '#exMpRoster').every((b) => b.left >= 0 && b.top >= 0 && b.right <= W && b.bottom <= H));
445	    check(`lái xe ${tag}: không bị lớp khác che`, (await Promise.all(DH.map((s) => topAtCenter(page, s)))).every(Boolean));
446	    const g = hud.find((b) => b.sel === '#drGas'), br = hud.find((b) => b.sel === '#drBrake'), st = hud.find((b) => b.sel === '#drSteer');
447	    check(`lái xe ${tag}: PHANH nhỏ hơn GA và nằm bên trái GA; cần gạt ở nửa trái`, br.width * br.height < g.width * g.height && br.right <= g.left && st.left + st.width / 2 < W / 2 && g.left > W / 2);
448	    return hud;
